jdbc_url = mssparkutils.credentials.getConnectionStringOrCreds(f"LS_{cfg['source']['system']}")
reader = spark.read.format("jdbc").option("url", jdbc_url)
if cfg["source"].get("query"):
    df = reader.option("query", cfg["source"].get("query")).load()
else:
    df = reader.option("dbtable", cfg["source"].get("table")).load()
